import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.loads(sys.stdin.read())
# Compare
for bp, ap in zip(baseline['projects'], after['projects']):
    bpkgs = {p['id']: p['resolvedVersion'] for f in bp['frameworks'] for p in f['topLevelPackages']}
    apkgs = {p['id']: p['resolvedVersion'] for f in ap['frameworks'] for p in f['topLevelPackages']}
    if bpkgs == apkgs:
        print(f'✅ {bp[\"path\"].split(\"/\")[-1]}: identical')
    else:
        print(f'❌ {bp[\"path\"].split(\"/\")[-1]}: DIFFERS')
        for k in set(list(bpkgs.keys()) + list(apkgs.keys())):
            if bpkgs.get(k) != apkgs.get(k):
                print(f'   {k}: {bpkgs.get(k)} -> {apkgs.get(k)}')
"

